do $$
begin
  if not exists (select 1 from pg_roles where rolname='programacion_test_generator') then
    create role programacion_test_generator nologin;
  end if;
end
$$;

grant usage on schema programacion to programacion_test_generator;

alter table programacion.test_contracts
  add column if not exists generation_source_sha256 text,
  add column if not exists generator_component_id bigint references programacion.componentes(id) on update restrict on delete restrict;

create index if not exists idx_test_contracts_generator_component
  on programacion.test_contracts(generator_component_id);

insert into programacion.componentes(version_id,componente_codigo,tipo,nombre,responsabilidad,orden_ejecucion,independencia_requerida,configuracion,estado)
select v.id,'TEST_CONTRACT_BLIND_GENERATOR','oracle','Blind pre-implementation Test Contract generator','Receives only the canonical functional/task generation source before implementation starts; no repository, diff, implementation, implementation reasoning, execution evidence or Context Pack input is part of its contract.',1,true,jsonb_build_object('channel','BLIND_PREIMPLEMENTATION_V1','source_function','programacion.fn_test_contract_generation_source','repo_access',false,'implementation_input',false,'diff_input',false,'implementation_reasoning_input',false,'execution_evidence_input',false,'context_pack_input',false),'defined'
from programacion.versiones_agente v where v.version_codigo='v0.9-roadmap-complete' and not exists(select 1 from programacion.componentes c where c.version_id=v.id and c.componente_codigo='TEST_CONTRACT_BLIND_GENERATOR');

insert into programacion.gates(version_id,gate_codigo,fase,tipo,nombre,descripcion,ejecutor_componente_id,modo_verificacion,reintentos_max,bloqueante,evidencia_requerida,configuracion,estado)
select v.id,'G_TASK_DAG','preparation','hard','Agent Task DAG decomposition policy','Mechanical DAG policy. Decomposed stories fail closed until max_pure_chain_length is explicitly calibrated; no universal threshold is embedded in code.',null,'deterministic',0,true,true,jsonb_build_object('threshold_status','TO_CALIBRATE'),'defined'
from programacion.versiones_agente v where v.version_codigo='v0.9-roadmap-complete' and not exists(select 1 from programacion.gates g where g.version_id=v.id and g.gate_codigo='G_TASK_DAG');

insert into programacion.gates(version_id,gate_codigo,fase,tipo,nombre,descripcion,ejecutor_componente_id,modo_verificacion,reintentos_max,bloqueante,evidencia_requerida,configuracion,estado)
select v.id,'G_TEST_CONTRACT_BLIND','preparation','hard','Blind Test Contract generation boundary','Test Contract generation source excludes implementation/diff/reasoning and closes as soon as an Agent Task execution exists.',c.id,'deterministic',0,true,true,c.configuracion,'defined'
from programacion.versiones_agente v join programacion.componentes c on c.version_id=v.id and c.componente_codigo='TEST_CONTRACT_BLIND_GENERATOR'
where v.version_codigo='v0.9-roadmap-complete' and not exists(select 1 from programacion.gates g where g.version_id=v.id and g.gate_codigo='G_TEST_CONTRACT_BLIND');

create or replace function programacion.fn_test_contract_generation_source(p_task_id bigint)
returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,programacion as $$
declare t programacion.agent_tasks%rowtype; f public.lf_functional_versions%rowtype; v_ac jsonb; v_inv jsonb; v_neg jsonb; v_source jsonb; v_digest text;
begin
 select * into t from programacion.agent_tasks where id=p_task_id; if t.id is null then raise exception 'agent task % not found',p_task_id; end if; if t.definition_status<>'SEALED' then raise exception 'blind generation source requires SEALED agent task'; end if;
 if exists(select 1 from programacion.ejecuciones ex where ex.request_ref='agent-task://'||t.id) then raise exception 'BLIND_SOURCE_CLOSED_AFTER_IMPLEMENTATION_START'; end if;
 select * into f from public.lf_functional_versions where id=t.functional_version_id; if f.id is null or f.status<>'SEALED' then raise exception 'blind generation source requires SEALED functional version'; end if;
 select coalesce(jsonb_agg(e order by e->>'code'),'[]'::jsonb) into v_ac from jsonb_array_elements(f.acceptance_criteria)e where e->>'code'=any(t.acceptance_refs);
 select coalesce(jsonb_agg(e order by e->>'code'),'[]'::jsonb) into v_inv from jsonb_array_elements(f.invariants)e where e->>'code'=any(t.invariant_refs);
 select coalesce(jsonb_agg(e order by e->>'code'),'[]'::jsonb) into v_neg from jsonb_array_elements(f.negative_controls)e where e->>'code'=any(t.negative_refs);
 if jsonb_array_length(v_ac)<>cardinality(t.acceptance_refs) or jsonb_array_length(v_inv)<>cardinality(t.invariant_refs) or jsonb_array_length(v_neg)<>cardinality(t.negative_refs) then raise exception 'blind generation source criteria mismatch'; end if;
 v_source:=jsonb_build_object('schema_version',1,'task',jsonb_build_object('id',t.id,'task_code',t.task_code,'task_version',t.task_version,'task_sha256',t.task_sha256,'objective',t.objective,'acceptance_refs',to_jsonb(t.acceptance_refs),'invariant_refs',to_jsonb(t.invariant_refs),'negative_refs',to_jsonb(t.negative_refs),'platform_refs',to_jsonb(t.platform_refs),'interface_refs',to_jsonb(t.interface_refs)),'functional_version',jsonb_build_object('id',f.id,'artifact_code',f.artifact_code,'artifact_type',f.artifact_type,'story_code',f.story_code,'version_no',f.version_no,'content_sha256',f.content_sha256,'objective',f.objective,'acceptance_criteria',v_ac,'invariants',v_inv,'negative_controls',v_neg,'source_rule_codes',to_jsonb(f.source_rule_codes)));
 v_digest:=programacion.fn_v09_sha256_jsonb(v_source); return v_source||jsonb_build_object('generation_source_sha256',v_digest);
end;$$;
revoke all on function programacion.fn_test_contract_generation_source(bigint) from public,anon,authenticated;
grant execute on function programacion.fn_test_contract_generation_source(bigint) to programacion_test_generator,programacion_human_authority,programacion_auditor;

create or replace function programacion.fn_task_dag_metrics(p_functional_version_id bigint)
returns jsonb language plpgsql stable set search_path=pg_catalog,programacion as $$
declare v_cfg jsonb; v_threshold integer; v_policy_status text; v_task_count integer; v_edge_count integer; v_root_count integer; v_leaf_count integer; v_branch_count integer; v_max_chain integer; v_structural_chain boolean; v_pure_chain boolean;
begin
 select g.configuracion into v_cfg from programacion.gates g join programacion.versiones_agente v on v.id=g.version_id where v.version_codigo='v0.9-roadmap-complete' and g.gate_codigo='G_TASK_DAG' and g.estado in('defined','active') order by g.id desc limit 1;
 if v_cfg is not null and coalesce(v_cfg->>'max_pure_chain_length','')~'^[0-9]+$' and (v_cfg->>'max_pure_chain_length')::integer>=2 then v_threshold:=(v_cfg->>'max_pure_chain_length')::integer;v_policy_status:='CONFIGURED'; else v_threshold:=null;v_policy_status:='MISSING'; end if;
 with recursive current_tasks as(select t.id from programacion.agent_tasks t where t.functional_version_id=p_functional_version_id and not exists(select 1 from programacion.agent_tasks n where n.supersedes_task_id=t.id)),edges as(select d.task_id,d.depends_on_task_id from programacion.task_dependencies d join current_tasks t on t.id=d.task_id join current_tasks p on p.id=d.depends_on_task_id),degrees as(select t.id,(select count(*) from edges e where e.task_id=t.id)indeg,(select count(*) from edges e where e.depends_on_task_id=t.id)outdeg from current_tasks t),roots as(select id from degrees where indeg=0),walk(node,depth,path)as(select r.id,1,array[r.id]::bigint[] from roots r union all select e.task_id,w.depth+1,w.path||e.task_id from walk w join edges e on e.depends_on_task_id=w.node where not e.task_id=any(w.path)) select(select count(*) from current_tasks),(select count(*) from edges),(select count(*) from degrees where indeg=0),(select count(*) from degrees where outdeg=0),(select count(*) from degrees where indeg>1 or outdeg>1),coalesce((select max(depth) from walk),0) into v_task_count,v_edge_count,v_root_count,v_leaf_count,v_branch_count,v_max_chain;
 if v_task_count<=1 then v_policy_status:='NOT_REQUIRED'; end if; v_structural_chain:=(v_task_count>1 and v_root_count=1 and v_leaf_count=1 and v_branch_count=0 and v_edge_count=v_task_count-1); v_pure_chain:=(v_policy_status='CONFIGURED' and v_structural_chain and v_max_chain>=v_threshold);
 return jsonb_build_object('task_count',v_task_count,'edge_count',v_edge_count,'root_count',v_root_count,'leaf_count',v_leaf_count,'branch_count',v_branch_count,'max_chain_length',v_max_chain,'structural_pure_chain',v_structural_chain,'pure_chain',v_pure_chain,'pure_chain_threshold',v_threshold,'pure_chain_policy_status',v_policy_status);
end;$$;

create or replace function programacion.fn_guard_agent_task_dag_policy() returns trigger language plpgsql set search_path=pg_catalog,programacion as $$ declare v_metrics jsonb; begin if tg_op='UPDATE' and old.definition_status='DRAFT' and new.definition_status='SEALED' then v_metrics:=programacion.fn_task_dag_metrics(new.functional_version_id); if coalesce((v_metrics->>'task_count')::integer,0)>1 and v_metrics->>'pure_chain_policy_status'='MISSING' then raise exception 'BLOCKED_POLICY_MISSING: G_TASK_DAG.max_pure_chain_length must be calibrated before sealing decomposed Agent Tasks'; end if; if coalesce((v_metrics->>'pure_chain')::boolean,false) then raise exception 'RECOMBINE_REQUIRED: pure task chain length % reaches configured threshold %',v_metrics->>'max_chain_length',v_metrics->>'pure_chain_threshold'; end if; end if; return new; end;$$;
drop trigger if exists trg_agent_tasks_00_dag_policy on programacion.agent_tasks; create trigger trg_agent_tasks_00_dag_policy before update on programacion.agent_tasks for each row execute function programacion.fn_guard_agent_task_dag_policy(); revoke all on function programacion.fn_guard_agent_task_dag_policy() from public,anon,authenticated;

create or replace function programacion.fn_guard_test_contract() returns trigger language plpgsql set search_path=pg_catalog,public,programacion as $$
declare v_task programacion.agent_tasks%rowtype;v_prior programacion.test_contracts%rowtype;v_component programacion.componentes%rowtype;v_source jsonb;v_source_sha text;v_payload jsonb;v_digest text;v_snapshot jsonb;v_cmd jsonb;
begin
 if tg_op='DELETE' then raise exception 'test contracts are append-only'; end if; if tg_op='UPDATE' and old.status='SEALED' then raise exception 'sealed test contract % is immutable; amend Spec/Task and create a new contract',old.id; end if; if tg_op='INSERT' and new.status<>'DRAFT' then raise exception 'test contract must be born DRAFT'; end if;
 select * into v_task from programacion.agent_tasks where id=new.task_id; if v_task.id is null or v_task.definition_status<>'SEALED' then raise exception 'test contract requires SEALED task'; end if; if exists(select 1 from programacion.ejecuciones ex where ex.request_ref='agent-task://'||v_task.id) then raise exception 'TEST_CONTRACT_AFTER_IMPLEMENTATION_START_REJECTED'; end if;
 select * into v_component from programacion.componentes where id=new.generator_component_id; if v_component.id is null or v_component.componente_codigo<>'TEST_CONTRACT_BLIND_GENERATOR' or v_component.independencia_requerida is not true or v_component.estado not in('defined','active') or coalesce((v_component.configuracion->>'repo_access')::boolean,true)is not false or coalesce((v_component.configuracion->>'implementation_input')::boolean,true)is not false or coalesce((v_component.configuracion->>'diff_input')::boolean,true)is not false or coalesce((v_component.configuracion->>'implementation_reasoning_input')::boolean,true)is not false or coalesce((v_component.configuracion->>'execution_evidence_input')::boolean,true)is not false or coalesce((v_component.configuracion->>'context_pack_input')::boolean,true)is not false or v_component.configuracion->>'source_function'<>'programacion.fn_test_contract_generation_source' or v_component.configuracion->>'channel'<>'BLIND_PREIMPLEMENTATION_V1' then raise exception 'test contract requires enforced TEST_CONTRACT_BLIND_GENERATOR component'; end if; if tg_op='UPDATE' and new.generator_component_id is distinct from old.generator_component_id then raise exception 'generator_component_id is immutable'; end if;
 v_source:=programacion.fn_test_contract_generation_source(v_task.id);v_source_sha:=v_source->>'generation_source_sha256';if new.generation_source_sha256 is not null and new.generation_source_sha256<>v_source_sha then raise exception 'generation source digest mismatch'; end if;new.generation_source_sha256:=v_source_sha;new.generator_identity:=v_component.componente_codigo;new.generator_channel:=v_component.configuracion->>'channel';
 if jsonb_typeof(new.visible_commands)<>'array' or jsonb_array_length(new.visible_commands)=0 then raise exception 'visible_commands must be non-empty array';end if;for v_cmd in select value from jsonb_array_elements(new.visible_commands)loop if jsonb_typeof(v_cmd)<>'object' or not(v_cmd?&array['name','argv','timeout_seconds','max_output_bytes']) or(select count(*)from jsonb_object_keys(v_cmd))<>4 or length(btrim(coalesce(v_cmd->>'name','')))=0 or(v_cmd->>'name')!~'^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$' or jsonb_typeof(v_cmd->'argv')<>'array' or jsonb_array_length(v_cmd->'argv')not between 1 and 64 or exists(select 1 from jsonb_array_elements(v_cmd->'argv')a where jsonb_typeof(a)<>'string' or length(a#>>'{}')=0 or octet_length(a#>>'{}')>4096) or(v_cmd->>'timeout_seconds')!~'^[0-9]+$' or(v_cmd->>'timeout_seconds')::integer not between 1 and 900 or(v_cmd->>'max_output_bytes')!~'^[0-9]+$' or(v_cmd->>'max_output_bytes')::integer not between 1024 and 2000000 then raise exception 'visible command does not match Worker acceptance command contract';end if;end loop;if(select count(*)from jsonb_array_elements(new.visible_commands))<>(select count(distinct c->>'name')from jsonb_array_elements(new.visible_commands)c)then raise exception 'visible command names must be unique';end if;
 if length(btrim(new.hidden_oracle_ref))=0 or new.hidden_oracle_ref!~'^[A-Za-z][A-Za-z0-9+.-]*://.+' then raise exception 'hidden_oracle_ref must be external URI';end if;if new.hidden_oracle_sha256!~'^[0-9a-f]{64}$' then raise exception 'hidden_oracle_sha256 invalid';end if;
 if new.supersedes_contract_id is null then if new.contract_version<>v_task.task_version then raise exception 'contract_version must equal task_version';end if;if new.amendment_reason_code is not null or new.amendment_ref is not null then raise exception 'initial task contract cannot carry amendment metadata';end if;else select * into v_prior from programacion.test_contracts where id=new.supersedes_contract_id;if v_prior.id is null or v_prior.status<>'SEALED' then raise exception 'superseded contract must be SEALED';end if;if v_task.supersedes_task_id is distinct from v_prior.task_id or new.contract_version<>v_prior.contract_version+1 then raise exception 'contract amendment requires superseding task version';end if;if length(btrim(coalesce(new.amendment_reason_code,'')))=0 or length(btrim(coalesce(new.amendment_ref,'')))=0 then raise exception 'contract amendment reason/ref required';end if;end if;
 if new.status='DRAFT' then if new.contract_sha256 is not null or new.sealed_at is not null then raise exception 'DRAFT test contract cannot carry seal';end if;else if tg_op<>'UPDATE' or old.status<>'DRAFT' then raise exception 'SEALED test contract requires DRAFT -> SEALED transition';end if;v_snapshot:=jsonb_build_object('acceptance_refs',to_jsonb(v_task.acceptance_refs),'invariant_refs',to_jsonb(v_task.invariant_refs),'negative_refs',to_jsonb(v_task.negative_refs),'task_sha256',v_task.task_sha256,'generation_source_sha256',new.generation_source_sha256);new.criteria_snapshot:=v_snapshot;v_payload:=jsonb_build_object('schema_version',1,'task_id',new.task_id,'task_sha256',v_task.task_sha256,'contract_version',new.contract_version,'supersedes_contract_id',new.supersedes_contract_id,'suite_code',new.suite_code,'visible_commands',new.visible_commands,'hidden_oracle_ref',new.hidden_oracle_ref,'hidden_oracle_sha256',new.hidden_oracle_sha256,'generator_component_id',new.generator_component_id,'generator_identity',new.generator_identity,'generator_channel',new.generator_channel,'generation_source_sha256',new.generation_source_sha256,'criteria_snapshot',new.criteria_snapshot,'amendment_reason_code',new.amendment_reason_code,'amendment_ref',new.amendment_ref);v_digest:=programacion.fn_v09_sha256_jsonb(v_payload);if new.contract_sha256 is not null and new.contract_sha256<>v_digest then raise exception 'test contract digest mismatch';end if;new.contract_sha256:=v_digest;new.sealed_at:=coalesce(new.sealed_at,now());end if;return new;
end;$$;

create or replace function programacion.fn_submit_blind_test_contract(p_task_id bigint,p_suite_code text,p_visible_commands jsonb,p_hidden_oracle_ref text,p_hidden_oracle_sha256 text,p_supersedes_contract_id bigint default null,p_amendment_reason_code text default null,p_amendment_ref text default null)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,programacion as $$declare v_task programacion.agent_tasks%rowtype;v_component_id bigint;v_source jsonb;v_contract_id bigint;v_result programacion.test_contracts%rowtype;begin select * into v_task from programacion.agent_tasks where id=p_task_id;if v_task.id is null or v_task.definition_status<>'SEALED' then raise exception 'blind contract submit requires SEALED Agent Task';end if;v_source:=programacion.fn_test_contract_generation_source(p_task_id);select c.id into v_component_id from programacion.componentes c join programacion.versiones_agente v on v.id=c.version_id where v.version_codigo='v0.9-roadmap-complete' and c.componente_codigo='TEST_CONTRACT_BLIND_GENERATOR' and c.estado in('defined','active')order by c.id desc limit 1;if v_component_id is null then raise exception 'TEST_CONTRACT_BLIND_GENERATOR component missing';end if;insert into programacion.test_contracts(task_id,contract_version,supersedes_contract_id,suite_code,visible_commands,hidden_oracle_ref,hidden_oracle_sha256,generator_identity,generator_channel,criteria_snapshot,amendment_reason_code,amendment_ref,status,generation_source_sha256,generator_component_id)values(p_task_id,v_task.task_version,p_supersedes_contract_id,p_suite_code,p_visible_commands,p_hidden_oracle_ref,p_hidden_oracle_sha256,'SYSTEM_DERIVED','SYSTEM_DERIVED','{}'::jsonb,p_amendment_reason_code,p_amendment_ref,'DRAFT',v_source->>'generation_source_sha256',v_component_id)returning id into v_contract_id;update programacion.test_contracts set status='SEALED' where id=v_contract_id returning * into v_result;return jsonb_build_object('contract_id',v_result.id,'task_id',v_result.task_id,'contract_version',v_result.contract_version,'status',v_result.status,'generator_identity',v_result.generator_identity,'generator_channel',v_result.generator_channel,'generation_source_sha256',v_result.generation_source_sha256,'contract_sha256',v_result.contract_sha256,'sealed_at',v_result.sealed_at);end;$$;
revoke all on function programacion.fn_submit_blind_test_contract(bigint,text,jsonb,text,text,bigint,text,text)from public,anon,authenticated;grant execute on function programacion.fn_submit_blind_test_contract(bigint,text,jsonb,text,text,bigint,text,text)to programacion_test_generator;revoke insert,update on programacion.test_contracts from programacion_verifier;drop policy if exists p_test_contracts_verifier_insert on programacion.test_contracts;drop policy if exists p_test_contracts_verifier_update on programacion.test_contracts;alter table programacion.test_contracts alter column generation_source_sha256 set not null,alter column generator_component_id set not null;

create or replace function programacion.fn_task_readiness(p_task_id bigint)returns jsonb language plpgsql stable set search_path=pg_catalog,public,programacion as $$declare t programacion.agent_tasks%rowtype;f public.lf_functional_versions%rowtype;tc programacion.test_contracts%rowtype;b record;d record;v_ready boolean:=true;v_exec boolean:=true;v_sizing text:='EXECUTABLE';v_blockers jsonb:='[]'::jsonb;v_waiting jsonb:='[]'::jsonb;v_metrics jsonb;begin select * into t from programacion.agent_tasks where id=p_task_id;if t.id is null then raise exception 'agent task % not found',p_task_id;end if;select * into f from public.lf_functional_versions where id=t.functional_version_id;select * into tc from programacion.test_contracts where task_id=t.id and status='SEALED';v_metrics:=programacion.fn_task_dag_metrics(t.functional_version_id);if exists(select 1 from programacion.agent_tasks n where n.supersedes_task_id=t.id)then v_ready:=false;v_blockers:=v_blockers||jsonb_build_array(jsonb_build_object('code','TASK_SUPERSEDED','owner_type','TASK_PREPARATION','required_action','USE_CURRENT_TASK_VERSION','source_ref','agent-task://'||t.id));end if;if f.status<>'SEALED' then v_ready:=false;v_blockers:=v_blockers||jsonb_build_array(jsonb_build_object('code','FUNCTIONAL_VERSION_NOT_SEALED','owner_type','FUNCTIONAL_OWNER','required_action','SEAL_FUNCTIONAL_VERSION','source_ref','functional-version://'||t.functional_version_id));end if;if t.definition_status<>'SEALED' then v_ready:=false;v_blockers:=v_blockers||jsonb_build_array(jsonb_build_object('code','TASK_NOT_SEALED','owner_type','TASK_PREPARATION','required_action','SEAL_AGENT_TASK','source_ref','agent-task://'||t.id));end if;if tc.id is null then v_ready:=false;v_blockers:=v_blockers||jsonb_build_array(jsonb_build_object('code','TEST_CONTRACT_NOT_SEALED','owner_type','TEST_CONTRACT_GENERATOR','required_action','GENERATE_AND_SEAL_BLIND_TEST_CONTRACT','source_ref','agent-task://'||t.id));end if;if cardinality(t.unknown_refs)>0 then v_ready:=false;v_sizing:='BLOCKED';v_blockers:=v_blockers||jsonb_build_array(jsonb_build_object('code','UNKNOWN_SCOPE_REFS','owner_type','TASK_PREPARATION','required_action','RESOLVE_UNKNOWNS','source_ref','agent-task://'||t.id));elsif cardinality(t.files_expected)>t.max_changed_files then v_ready:=false;v_sizing:='REVIEW_SPLIT';v_blockers:=v_blockers||jsonb_build_array(jsonb_build_object('code','SIZING_REVIEW_SPLIT','owner_type','TASK_PREPARATION','required_action','SPLIT_OR_REDUCE_SCOPE','source_ref','agent-task://'||t.id));end if;if coalesce((v_metrics->>'task_count')::integer,0)>1 and v_metrics->>'pure_chain_policy_status'='MISSING' then v_ready:=false;v_blockers:=v_blockers||jsonb_build_array(jsonb_build_object('code','DAG_POLICY_MISSING','owner_type','HUMAN_PLAN','required_action','CALIBRATE_G_TASK_DAG_MAX_PURE_CHAIN_LENGTH','source_ref','gate://G_TASK_DAG'));elsif coalesce((v_metrics->>'pure_chain')::boolean,false)then v_ready:=false;v_blockers:=v_blockers||jsonb_build_array(jsonb_build_object('code','PURE_CHAIN_RECOMBINE_REQUIRED','owner_type','TASK_PREPARATION','required_action','RECOMBINE_TASKS','source_ref','functional-version://'||t.functional_version_id));end if;for b in select * from programacion.task_blockers where task_id=t.id and status='OPEN' loop v_ready:=false;v_blockers:=v_blockers||jsonb_build_array(jsonb_build_object('code',b.blocker_code,'owner_type',b.owner_type,'owner_ref',b.owner_ref,'required_action',b.required_action,'source_ref',b.source_ref));end loop;for d in select depends_on_task_id from programacion.task_dependencies where task_id=t.id order by depends_on_task_id loop if exists(select 1 from programacion.agent_tasks n where n.supersedes_task_id=d.depends_on_task_id)or not exists(select 1 from programacion.agent_tasks x where x.id=d.depends_on_task_id and x.definition_status='SEALED')then v_ready:=false;v_blockers:=v_blockers||jsonb_build_array(jsonb_build_object('code','DEPENDENCY_TASK_NOT_CURRENT_SEALED','owner_type','TASK_PREPARATION','required_action','RESOLVE_DEPENDENCY_TASK','source_ref','agent-task://'||d.depends_on_task_id));end if;if not exists(select 1 from programacion.v_ejecucion_autoridad ea join programacion.ejecuciones ex on ex.id=ea.execution_id where ex.request_ref='agent-task://'||d.depends_on_task_id and ea.effective_verdict='PASS')then v_exec:=false;v_waiting:=v_waiting||jsonb_build_array(d.depends_on_task_id);end if;end loop;if not v_ready then v_exec:=false;end if;return jsonb_build_object('task_id',t.id,'task_code',t.task_code,'task_version',t.task_version,'ready_for_development',v_ready,'executable_now',v_exec,'sizing',v_sizing,'sizing_metrics',jsonb_build_object('files_expected',cardinality(t.files_expected),'dependency_count',(select count(*)from programacion.task_dependencies where task_id=t.id),'platform_count',cardinality(t.platform_refs),'interface_count',cardinality(t.interface_refs),'unknown_count',cardinality(t.unknown_refs)),'dag',v_metrics,'blockers',v_blockers,'waiting_on_task_ids',v_waiting);end;$$;

create or replace function programacion.fn_agent_task_execution_bundle(p_task_id bigint,p_base_head_sha text,p_source_snapshot_sha256 text)returns jsonb language plpgsql stable set search_path=pg_catalog,public,programacion as $$declare t programacion.agent_tasks%rowtype;f public.lf_functional_versions%rowtype;tc programacion.test_contracts%rowtype;r jsonb;v_spec jsonb;v_preimage jsonb;v_bundle_sha text;begin if p_base_head_sha!~'^[0-9a-f]{40}$' or p_source_snapshot_sha256!~'^[0-9a-f]{64}$' then raise exception 'invalid source identity';end if;r:=programacion.fn_task_readiness(p_task_id);if not coalesce((r->>'ready_for_development')::boolean,false)then raise exception 'TASK_NOT_READY: %',r->'blockers';end if;if not coalesce((r->>'executable_now')::boolean,false)then raise exception 'TASK_WAITING_DEPENDENCIES: %',r->'waiting_on_task_ids';end if;select * into t from programacion.agent_tasks where id=p_task_id;select * into f from public.lf_functional_versions where id=t.functional_version_id;select * into tc from programacion.test_contracts where task_id=t.id and status='SEALED';v_spec:=jsonb_build_object('schema_version',1,'task_id',t.task_code||'.v'||t.task_version,'objective',t.objective,'base_head_sha',p_base_head_sha,'source_snapshot_sha256',p_source_snapshot_sha256,'context_path_patterns',to_jsonb(t.context_path_patterns),'write_path_patterns',to_jsonb(t.write_path_patterns),'protected_path_patterns',to_jsonb(t.protected_path_patterns),'acceptance_commands',tc.visible_commands,'max_attempts',t.max_attempts,'max_patch_bytes',t.max_patch_bytes,'max_changed_files',t.max_changed_files,'max_context_bytes',t.max_context_bytes,'allow_deletions',t.allow_deletions);v_preimage:=jsonb_build_object('request_ref','agent-task://'||t.id,'worker_task_spec',v_spec,'hidden_oracle_ref',tc.hidden_oracle_ref,'hidden_oracle_sha256',tc.hidden_oracle_sha256,'functional_version_sha256',f.content_sha256,'task_sha256',t.task_sha256,'test_contract_sha256',tc.contract_sha256,'readiness',r);v_bundle_sha:=programacion.fn_v09_sha256_jsonb(v_preimage);return v_preimage||jsonb_build_object('bundle_sha256',v_bundle_sha);end;$$;

create or replace function programacion.fn_guard_execution_insert()returns trigger language plpgsql set search_path=pg_catalog,public,programacion as $$declare v_task_id bigint;v_ready jsonb;v_task programacion.agent_tasks%rowtype;v_f public.lf_functional_versions%rowtype;v_tc programacion.test_contracts%rowtype;v_bundle jsonb;v_expected_scope jsonb;begin if new.estado is distinct from'CREATED' then raise exception 'execution must start CREATED; observed estado=%',coalesce(new.estado,'<NULL>');end if;if new.veredicto is not null or new.completed_at is not null or new.bloqueo_razon is not null then raise exception 'new CREATED execution cannot carry terminal verdict/completion/block reason';end if;if new.request_ref like'agent-task://%' then begin v_task_id:=substring(new.request_ref from 14)::bigint;exception when others then raise exception 'invalid agent-task request_ref';end;v_ready:=programacion.fn_task_readiness(v_task_id);if not coalesce((v_ready->>'ready_for_development')::boolean,false)then raise exception 'agent task is not READY_FOR_DEVELOPMENT: %',v_ready->'blockers';end if;if not coalesce((v_ready->>'executable_now')::boolean,false)then raise exception 'agent task is not EXECUTABLE_NOW: %',v_ready->'waiting_on_task_ids';end if;select * into v_task from programacion.agent_tasks where id=v_task_id;select * into v_f from public.lf_functional_versions where id=v_task.functional_version_id;select * into v_tc from programacion.test_contracts where task_id=v_task.id and status='SEALED';v_bundle:=programacion.fn_agent_task_execution_bundle(v_task_id,new.head_sha,new.source_snapshot_sha256);v_expected_scope:=jsonb_build_object('task_id',v_task.id,'task_sha256',v_task.task_sha256,'functional_version_sha256',v_f.content_sha256,'test_contract_sha256',v_tc.contract_sha256,'bundle_sha256',v_bundle->>'bundle_sha256','write_path_patterns',to_jsonb(v_task.write_path_patterns),'protected_path_patterns',to_jsonb(v_task.protected_path_patterns));if new.scope is distinct from v_expected_scope then raise exception 'execution scope does not match sealed agent task contract and pinned bundle digest';end if;end if;return new;end;$$;

revoke execute on function programacion.fn_task_dag_metrics(bigint)from public,anon,authenticated;revoke execute on function programacion.fn_task_readiness(bigint)from public,anon,authenticated;revoke execute on function programacion.fn_agent_task_execution_bundle(bigint,text,text)from public,anon,authenticated;grant execute on function programacion.fn_task_dag_metrics(bigint),programacion.fn_task_readiness(bigint),programacion.fn_agent_task_execution_bundle(bigint,text,text)to programacion_builder,programacion_auditor,programacion_human_authority,programacion_verifier;